import sailpoint.object.Application;
import sailpoint.object.Link;

String first = null;
String last = null;

// Read from the HR account; fall back to the identity's own names
Application app = context.getObjectByName(Application.class, "HR Authoritative CSV");
Link hr = (app == null) ? null : identity.getLink(app);
if (hr != null) {
    first = (String) hr.getAttribute("firstName");
    last  = (String) hr.getAttribute("lastName");
}
if (first == null) first = identity.getFirstname();
if (last == null)  last  = identity.getLastname();

StringBuilder dn = new StringBuilder();
if (first != null && first.trim().length() > 0) dn.append(first.trim());
if (last != null && last.trim().length() > 0) {
    if (dn.length() > 0) dn.append(" ");
    dn.append(last.trim());
}

// Nothing to build from: keep what we had
return dn.length() > 0 ? dn.toString() : oldValue;
